mapper.sql:
FROM fit_order_item oi
INNER JOIN fit_order o ON o.order_id = oi.order_id AND o.del_flag = '0'
LEFT JOIN fit_store st ON st.store_id = o.store_id AND st.del_flag = '0'
LEFT JOIN fit_member m ON m.member_id = o.member_id AND m.del_flag = '0'
WHERE oi.del_flag = '0'
AND oi.order_id = #{bo.orderId}
AND o.order_no LIKE CONCAT('%', #{bo.orderNo}, '%')
AND o.store_id = #{bo.storeId}
AND o.member_id = #{bo.memberId}
AND oi.item_type = #{bo.itemType}
AND oi.item_name LIKE CONCAT('%', #{bo.itemName}, '%')
AND o.create_time >= #{bo.orderCreateTimeStart}
AND o.create_time < DATE_ADD(#{bo.orderCreateTimeEnd}, INTERVAL 1 DAY)
